    /* ---------- Estudo de caso: Circuito Cinemas (projetos/circuito-cinemas.html) ---------- */
    "cc.meta.title": "Circuito Cinemas: case study | Gabriel Rocha",
    "cc.meta.description": "A concept redesign of a movie theater chain’s app: an audit with 34 friction points, new navigation, a 4-step purchase, a visible Circuito Club, and a design system.",
    "cc.meta.og-title": "Circuito Cinemas: case study | Gabriel Rocha",
    "cc.meta.og-description": "A concept redesign of a movie theater chain’s app: from diagnosis to screens and a design system, with assumptions kept separate from decisions.",
